    "content": "<div class=\"absolute inset-0 z-10 pointer-events-none\"><div class=\"absolute inset-0 z-10 transition-all duration-300\" style=\"background-color: rgb(255, 255, 255);\"></div></div><div id=\"post-content-container\" class=\"relative z-10 container mx-auto px-5 md:px-6 pt-10 pb-14 lg:pt-14 lg:pb-28\"><div id=\"wysiwyg-toolbar-container\" class=\"max-w-240 mx-auto\"><div class=\"wysiwyg-editor website-wysiwyg rich-text-block max-w-160 mx-auto !border-none !rounded-none placeholder-current !ring-0\"><div id=\"tiny-react_36848613521791272682449\"></div></div></div></div><div id=\"end-of-content\" class=\"absolute\" style=\"background-color: transparent; bottom: -40px;\"></div>",
